let db;try{db=JSON.parse(localStorage.getItem('esepter-v1'))||structuredClone(seed)}catch{db=structuredClone(seed)}
let route=location.hash.slice(1)||'overview', filter='', schoolFilter='all', tab='all', selectedAnswer=null, feedback=null, modalFocus=null;
const save=()=>{try{localStorage.setItem('esepter-v1',JSON.stringify(db))}catch{toast('Browser storage is unavailable. Changes last for this session.')}};
const roleNames={student:'Amina',teacher:'Dana',admin:'Marat'};
const roleFull=()=>db.role==='student'?db.name:db.role==='teacher'?'Dana Akhmetova':'Marat Ilyas';
const initials=n=>n.split(' ').map(x=>x[0]).slice(0,2).join('');
const topicName=id=>db.topics.find(t=>t.id===Number(id))?.name||'Archived topic';
const studentTopics=()=>db.topics.filter(t=>t.school==='s1');
const currentTopic=()=>studentTopics().find(t=>!db.passed.includes(t.id));
const allowedSchools=()=>db.role==='teacher'?db.schools.filter(s=>['s1','s2'].includes(s.id)):db.schools;
const visibleTopics=()=>db.role==='admin'?db.topics:db.topics.filter(t=>db.role==='student'?t.school==='s1':['s1','s2'].includes(t.school));
const visibleUsers=()=>db.users.map(u=>u.id==='u1'?{...u,name:db.name,email:db.email,passed:db.passed.length,score:Math.round(db.results.reduce((a,r)=>a+r.score,0)/Math.max(1,db.results.length))}:u).filter(u=>db.role==='admin'||u.school.split(',').some(x=>['s1','s2'].includes(x)));
const schoolName=id=>db.schools.find(s=>s.id===id)?.name||'School';
const dateLabel=s=>`<time datetime="${esc(s)}">${EsepterI18n.date(s)}</time>`;
function toast(message){$('#toast').textContent=message;$('#toast').classList.add('show');clearTimeout(window.toastTimer);window.toastTimer=setTimeout(()=>$('#toast').classList.remove('show'),3400)}
function go(next){filter='';tab='all';schoolFilter='all';if(route===next){render();return}location.hash=next}
window.addEventListener('hashchange',()=>{route=location.hash.slice(1)||'overview';filter='';tab='all';render();window.scrollTo(0,0)});
function badge(text,type=''){return `<span class="badge ${type}">${text}</span>`}
function brand(){return `<a class="brand" href="#welcome" aria-label="Esepter home"><span class="brandmark">e</span><span>esepter<span class="dot">.kz</span></span></a>`}
const menus={student:[['overview','grid','Overview'],['topics','book','My topics'],['results','chart','My results'],['achievements','award','Achievements']],teacher:[['overview','grid','Overview'],['students','users','Students'],['topics','book','Topics'],['questions','question','Question bank'],['analytics','chart','Analytics']],admin:[['overview','grid','Overview'],['schools','school','Schools'],['users','users','Users & roles'],['topics','book','Topics'],['questions','question','Question bank'],['analytics','chart','Monitoring']]};
function layout(content){const nav=menus[db.role];const title=nav.find(n=>n[0]===route)?.[2]||({exam:'Topic exam',settings:'Settings',result:'Exam result'}[route])||'Workspace';return `<div class="mobile-shade" data-action="menu"></div><aside class="sidebar">${brand()}<div class="school-switch"><span class="school-icon">${icon('school',true)}</span><div><strong>${db.role==='admin'?'All schools':'Nazarbayev Intellectual'}</strong><div class="muted" style="margin-top:3px">${db.role==='student'?'Grade 8 · Almaty':db.role==='teacher'?'2 assigned schools':'Platform administration'}</div></div></div><p class="navlabel">${db.role==='student'?'LEARNING SPACE':'WORKSPACE'}</p><nav class="nav">${nav.map(([r,i,n])=>`<a href="#${r}" class="${route===r?'active':''}">${icon(i)}${n}${r==='topics'&&db.role==='student'?`<span class="count">${studentTopics().length}</span>`:''}</a>`).join('')}</nav><div class="sidebar-bottom"><div class="helpbox">${icon('help')}<h4>A little help goes a long way</h4><p>Find your way around your math learning space.</p><button data-action="help">Visit help center ${icon('arrow',true)}</button></div><a href="#settings">${icon('settings',true)}Settings</a><a href="#login">${icon('logout',true)}Switch account</a></div></aside><div class="shell"><header class="topbar"><div class="row"><button class="iconbtn mobile-menu" data-action="menu" aria-label="Open navigation">${icon('menu')}</button><div class="breadcrumb"><span>${db.role[0].toUpperCase()+db.role.slice(1)} workspace</span>${icon('chevron',true)}<strong>${title}</strong></div></div><div class="top-actions"><div class="top-search">${icon('search',true)}<button data-action="search">Search anything</button></div><label class="role-control"><span>Demo</span><select id="role-select" aria-label="Preview role">${['student','teacher','admin'].map(r=>`<option ${r===db.role?'selected':''} value="${r}">${r[0].toUpperCase()+r.slice(1)}</option>`).join('')}</select></label><button class="iconbtn bell" data-action="notifications" aria-label="Notifications">${icon('bell')}</button><a class="avatar" href="#settings" aria-label="Your profile">${initials(roleFull())}</a></div></header><main class="main">${content}<footer class="page-footer"><span>© 2026 Esepter.kz. Every step counts.</span><span>Interactive preview · Sample school data</span></footer></main></div>`}
function heading(title,sub,action=''){return `<div class="page-head"><div><h1>${title}</h1><p>${sub}</p></div>${action||`<span class="date-chip">${icon('calendar',true)}Monday, 12 October 2026</span>`}</div>`}
function stat(i,label,value,suffix,sub){return `<article class="stat"><div class="top">${icon(i,true)}${label}</div><div class="statnum">${value}<small>${suffix}</small></div><div class="sub">${sub}</div></article>`}
function topicCard(t){const passed=db.passed.includes(t.id),current=currentTopic()?.id===t.id, locked=!passed&&!current;const score=db.best[t.id]||0;return `<article class="topic-card ${current?'current':''} ${locked?'locked':''}"><div class="topic-top"><span class="topic-icon">${esc(t.symbol)}</span>${badge(passed?'Completed':current?'In progress':'Locked',locked?'gray':'')}</div><h3>${esc(t.name)}</h3><p>${t.questions} questions · ${passed?'Topic passed':current?'Your next milestone':'Coming up next'}</p><div class="progress-track"><span style="width:${passed?100:score}%"></span></div><div class="topic-footer"><span>${passed?`Best score: ${score}/100`:current?'70 points to pass':`Complete the previous topic`}</span>${icon(passed?'check':locked?'lock':'arrow',true)}</div><button class="topic-action" data-action="topic" data-id="${t.id}" aria-label="${locked?'View unlock requirements for':'Open'} ${esc(t.name)}"></button></article>`}
function resultsTable(results=db.results,limit=99){return `<div class="activity-table table-wrap"><table><thead><tr><th>Topic</th><th>Date</th><th>Score</th><th>Result</th><th></th></tr></thead><tbody>${results.slice(0,limit).map(r=>`<tr class="clickable" data-action="result-detail" data-id="${r.id}"><td><div class="topic-cell"><span class="topic-icon">${esc(db.topics.find(t=>t.id===r.topic)?.symbol||'x')}</span><strong>${esc(topicName(r.topic))}</strong></div></td><td>${dateLabel(r.date)}</td><td class="score">${r.score}<small> /100</small></td><td>${badge(r.pass?'Passed':'Keep practicing',r.pass?'':'gold')}</td><td>${icon('chevron',true)}</td></tr>`).join('')||'<tr><td colspan="5" class="empty">No results yet. Your first exam is a good place to start.</td></tr>'}</tbody></table></div>`}
function studentOverview(){const ct=currentTopic();const avg=Math.round(db.results.reduce((a,r)=>a+r.score,0)/db.results.length)||0;return heading(`A little progress, every day <span style="font-size:25px">✦</span>`,`Welcome back, ${esc(db.name.split(' ')[0])}. Ready to take your next step in math?`)+`<div class="dashboard-grid"><div class="main-column"><section class="hero"><div class="copy"><span class="eyebrow">YOUR NEXT CHAPTER</span><h2>${ct?'Let’s make the<br>unknown, known.':'Look how far<br>you’ve come.'}</h2><p>${ct?`Continue with ${esc(ct.name.toLowerCase())} and turn small steps into big understanding.`:'You’ve completed every topic. Revisit an exam to keep your skills sharp.'}</p><button class="btn" data-action="start" data-id="${db.exam?.topic||ct?.id||1}">${db.exam?'Resume learning':ct?'Continue learning':'Practice again'} ${icon('arrow',true)}</button></div><div class="math-art" aria-hidden="true"><div class="orbit"></div><div class="orbit two"></div><div class="orb">x²</div><span class="formula">a + b = ?</span><span class="formula two">one step closer</span><span class="star">✦</span></div></section><div class="stats">${stat('book','Topics completed',db.passed.length,`/ ${studentTopics().length}`,'<b>Keep going</b> · You’re making progress')}${stat('target','Average score',avg,'/ 100','<b>Nice work</b> · Across your attempts')}${stat('clock','Questions answered',db.results.reduce((a,r)=>a+r.answers,0),'','Every question builds confidence')}</div><section><div class="section-title"><h2>Your learning path</h2><a class="textlink" href="#topics">View all topics ${icon('arrow',true)}</a></div><div class="topic-grid">${studentTopics().slice(Math.max(0,db.passed.length-1),Math.max(0,db.passed.length-1)+3).map(topicCard).join('')}</div></section><section><div class="section-title"><h2>Recent activity</h2><a class="textlink" href="#results">All results ${icon('arrow',true)}</a></div>${resultsTable(db.results,3)}</section></div><aside class="side-column"><section class="panel"><div class="row between"><h3>A little every day</h3><span class="badge gold">${icon('fire',true)}3 days</span></div><div class="week">${['M','T','W','T','F','S','S'].map((d,i)=>`<div class="day"><span data-weekday="${i}">${d}</span><b class="${i===0?'today':i>4?'done':''}">${i>4?icon('check',true):12+i}</b></div>`).join('')}</div><div class="streak-note">You showed up. That’s what matters.<br><strong>Make today another good day.</strong></div></section><section class="panel"><div class="row between"><h3>Your topic journey</h3>${icon('target',true)}</div><div class="weekly-progress"><div class="ring" style="background:conic-gradient(#99b767 0 ${db.passed.length/studentTopics().length*100}%,#edf1e5 0)"><div><strong>${db.passed.length}/${studentTopics().length}</strong><small>TOPICS</small></div></div><div><b>One step at a time</b><p>${studentTopics().length-db.passed.length} more topics to complete your learning path.</p></div></div></section><section class="tip-card"><span class="eyebrow">A SMALL REMINDER</span><h3>“Mistakes are proof<br>that you’re trying.”</h3><p>Take your time. Read it again.<br>You’re learning with every answer.</p><span class="tip-decoration" aria-hidden="true">✦</span></section><section class="panel"><h3>Your latest milestone</h3><div class="milestone"><span class="medal">${icon('award')}</span><div><h4>Foundation builder</h4><p>Completed your first two topics</p></div></div></section></aside></div>`}
function topicView(){if(db.role!=='student')return manageTopics();let ts=studentTopics().filter(t=>EsepterI18n.search(t.name,filter)).filter(t=>tab==='all'||(tab==='completed'?db.passed.includes(t.id):tab==='current'?t.id===currentTopic()?.id:!db.passed.includes(t.id)&&t.id!==currentTopic()?.id));return heading('Your learning path','One topic at a time. A stronger foundation with every step.')+`<div class="filters"><div class="segmented">${[['all','All topics'],['current','In progress'],['completed','Completed']].map(([id,label])=>`<button data-action="tab" data-id="${id}" class="${tab===id?'active':''}">${label}</button>`).join('')}</div><div class="search-input">${icon('search',true)}<input class="input" id="filter" value="${esc(filter)}" placeholder="Search topics…" aria-label="Search topics"></div></div><div class="topic-grid full">${ts.map(topicCard).join('')}</div>${!ts.length?empty('No topics found','Try a different search or filter.'):''}`}
function empty(title,text){return `<div class="empty">${icon('search')}<h3>${title}</h3><p>${text}</p></div>`}
function schoolOptions(){return `<select class="input" id="school-filter" aria-label="Filter by school"><option value="all">All ${db.role==='teacher'?'assigned ':''}schools</option>${allowedSchools().map(s=>`<option value="${s.id}" ${schoolFilter===s.id?'selected':''}>${esc(s.name)}</option>`).join('')}</select>`}
function educatorOverview(){const isAdmin=db.role==='admin';let users=visibleUsers().filter(u=>u.role==='student'&&(schoolFilter==='all'||u.school===schoolFilter));const avg=Math.round(users.reduce((a,u)=>a+u.score,0)/users.length)||0;return heading(`Good morning, ${roleNames[db.role]}.`,isAdmin?'A clear view of your schools, learners, and their next steps.':'Help every student move one step forward.',`<button class="btn" data-action="${isAdmin?'add-user':'add-topic'}">${icon('plus',true)}${isAdmin?'Create user':'Create topic'}</button>`)+`<div class="filters">${schoolOptions()}<span class="hint">Sample pilot overview</span></div><div class="stats">${stat('users','Students in view',users.length,'','Active student profiles in this preview')}${stat('target','Average score',avg,'/ 100','Across students in selected schools')}${stat('book',isAdmin?'Schools':'Published topics',isAdmin?db.schools.length:visibleTopics().length,'',isAdmin?'Connected to the platform':'Available in your assigned schools')}</div><div class="analytics-grid"><section class="panel"><div class="section-title"><h2>Learning activity</h2>${badge('Last 7 days','gray')}</div><p class="small muted">Completed exam attempts · sample pilot data</p>${chart([14,22,18,31,26,12,28],['Tue','Wed','Thu','Fri','Sat','Sun','Mon'])}</section><section class="panel"><h2>Students who need a hand</h2><p class="small muted" style="margin-top:7px">A little support can make a big difference.</p>${users.filter(u=>u.score<80).slice(0,3).map(u=>`<button class="row" data-action="student-detail" data-id="${u.id}" style="width:100%;padding:18px 0;border-bottom:1px solid var(--border);text-align:left"><span class="avatar mint">${initials(u.name)}</span><span class="stack" style="flex:1"><strong style="font-size:12px">${esc(u.name)}</strong><span class="muted small">${u.score}/100 average score</span></span>${icon('chevron',true)}</button>`).join('')||'<p style="margin-top:24px" class="muted">Everyone in this view is progressing well.</p>'}</section></div><div class="section-title"><h2>Student progress</h2><a class="textlink" href="#${isAdmin?'users':'students'}">View all ${icon('arrow',true)}</a></div>${usersTable(users.slice(0,5),false)}`}
function chart(values,labels){const max=Math.max(...values,1);return `<div class="chart">${values.map((v,i)=>`<div class="chart-column"><small>${v}</small><div class="chart-bar ${i===values.length-1?'dark':''}" style="height:${v/max*85}%" title="${labels[i]}: ${v}"></div><span>${labels[i]}</span></div>`).join('')}</div>`}
function usersTable(users,management=true){return `<div class="activity-table table-wrap"><table><thead><tr><th>${management?'Name':'Student'}</th><th>School</th><th>${management?'Role':'Progress'}</th><th>${management?'Status':'Average score'}</th><th></th></tr></thead><tbody>${users.map((u,i)=>`<tr><td><button class="topic-cell" data-action="student-detail" data-id="${u.id}" style="text-align:left"><span class="avatar ${i%2?'purple':'mint'}">${initials(u.name)}</span><span class="stack"><strong>${esc(u.name)}</strong><span class="small muted">${management?esc(u.email):'Grade 8'}</span></span></button></td><td>${u.role==='admin'?'All schools':u.school.split(',').map(s=>esc(schoolName(s))).join('<br>')}</td><td>${management?badge(u.role[0].toUpperCase()+u.role.slice(1),u.role==='teacher'?'gold':''):`${u.passed} of 8 topics`}</td><td>${management?badge('Active'):`<span class="score">${u.score}<small> /100</small></span>`}</td><td>${management&&db.role==='admin'?`<button class="iconbtn" data-action="edit-user" data-id="${u.id}" aria-label="Edit ${esc(u.name)}">${icon('edit',true)}</button>`:`<button class="iconbtn" data-action="student-detail" data-id="${u.id}" aria-label="View ${esc(u.name)}">${icon('chevron',true)}</button>`}</td></tr>`).join('')||'<tr><td colspan="5" class="empty">No matching students or users.</td></tr>'}</tbody></table></div>`}
function usersView(){const admin=db.role==='admin';let users=visibleUsers().filter(u=>admin||u.role==='student').filter(u=>EsepterI18n.search(u.name+' '+u.email,filter)&&(schoolFilter==='all'||u.school.split(',').includes(schoolFilter))&&(tab==='all'||u.role===tab));return heading(admin?'People make progress possible':'Every student, a different journey',admin?'Manage accounts, school assignments, and roles.':'See how your students are doing and where they need support.',admin?`<button class="btn" data-action="add-user">${icon('plus',true)}Create user</button>`:'')+`<div class="filters"><div class="search-input">${icon('search',true)}<input class="input" id="filter" value="${esc(filter)}" placeholder="Search by name or email…" aria-label="Search users"></div>${schoolOptions()}${admin?`<select class="input" id="tab-filter" aria-label="Filter role"><option value="all">All roles</option>${['student','teacher','admin'].map(r=>`<option ${tab===r?'selected':''} value="${r}">${r}</option>`).join('')}</select>`:''}</div>${usersTable(users,admin)}<p class="hint" style="margin-top:17px">Showing ${users.length} ${admin?'users':'students'} · ${admin?'All schools':'Your assigned schools only'}</p>`}
function manageTopics(){const ts=visibleTopics().filter(t=>EsepterI18n.search(t.name,filter)&&(schoolFilter==='all'||t.school===schoolFilter));return heading('A clear path to understanding','Organize topics and give every school a structured learning journey.',`<button class="btn" data-action="add-topic">${icon('plus',true)}Create topic</button>`)+`<div class="filters"><div class="search-input">${icon('search',true)}<input class="input" id="filter" value="${esc(filter)}" placeholder="Search topics…" aria-label="Search topics"></div>${schoolOptions()}</div><div class="activity-table table-wrap"><table><thead><tr><th>Topic</th><th>School</th><th>Questions</th><th>Status</th><th>Actions</th></tr></thead><tbody>${ts.map(t=>`<tr><td><div class="topic-cell"><span class="topic-icon">${esc(t.symbol)}</span><span class="stack"><strong>${esc(t.name)}</strong><span class="small muted">${esc(t.desc)}</span></span></div></td><td>${esc(schoolName(t.school))}</td><td>${t.questions}</td><td>${badge('Published')}</td><td><div class="row"><button class="iconbtn" data-action="edit-topic" data-id="${t.id}" aria-label="Edit topic">${icon('edit',true)}</button><button class="iconbtn" data-action="topic-questions" data-id="${t.id}" aria-label="View questions">${icon('question',true)}</button></div></td></tr>`).join('')||'<tr><td colspan="5" class="empty">No topics match your search.</td></tr>'}</tbody></table></div><p class="hint" style="margin-top:18px">Topics follow the order shown within each school. Students unlock the next topic at 70 points.</p>`}
function questionsView(){let qs=db.questions.filter(q=>visibleTopics().some(t=>t.id===q.topic)).filter(q=>(EsepterI18n.search(q.prompt,filter)||EsepterI18n.search(topicName(q.topic),filter))&&(tab==='all'||q.difficulty===tab));return heading('Good questions open new doors','Create and manage your school’s mathematics question bank.',`<button class="btn" data-action="add-question">${icon('plus',true)}Add question</button>`)+`<div class="filters"><div class="search-input">${icon('search',true)}<input class="input" id="filter" value="${esc(filter)}" placeholder="Search questions or topics…" aria-label="Search questions"></div><select class="input" id="tab-filter" aria-label="Filter difficulty"><option value="all">All difficulties</option>${['Easy','Medium','Hard'].map(d=>`<option ${tab===d?'selected':''}>${d}</option>`).join('')}</select></div><div class="activity-table table-wrap"><table><thead><tr><th>Question</th><th>Topic</th><th>Difficulty</th><th>Mode</th><th></th></tr></thead><tbody>${qs.map(q=>`<tr><td><strong>${esc(q.prompt)}</strong><p class="small muted" style="margin-top:5px">Answer: ${esc(q.answer)}</p></td><td>${esc(topicName(q.topic))}</td><td>${badge(q.difficulty,q.difficulty==='Hard'?'gold':'')}</td><td>${q.mode}</td><td><div class="row"><button class="iconbtn" data-action="edit-question" data-id="${q.id}" aria-label="Edit question">${icon('edit',true)}</button><button class="iconbtn" data-action="delete-question" data-id="${q.id}" aria-label="Delete question">${icon('trash',true)}</button></div></td></tr>`).join('')||'<tr><td colspan="5" class="empty">No questions found. Add one to get started.</td></tr>'}</tbody></table></div><p class="hint" style="margin-top:18px">${qs.length} authored questions · Student exams also use generated practice questions.</p>`}
function schoolsView(){return heading('Connected schools, shared progress','Give every school a place to help its students grow.',`<button class="btn" data-action="add-school">${icon('plus',true)}Add school</button>`)+`<div class="filters"><div class="search-input">${icon('search',true)}<input class="input" id="filter" value="${esc(filter)}" placeholder="Search schools or cities…" aria-label="Search schools"></div></div><div class="school-grid">${db.schools.filter(s=>(EsepterI18n.search(s.name,filter)||EsepterI18n.search(s.city,filter))).map(s=>`<article class="school-card"><div class="row between" style="margin:0"><span class="topic-icon">${icon('school')}</span>${badge('Active')}</div><h3>${esc(s.name)}</h3><p class="small muted">${esc(s.city)}, Kazakhstan</p><div class="row"><div><strong>${s.students}</strong><span>Students</span></div><div><strong>${s.teachers}</strong><span>Teachers</span></div></div><button class="btn light" data-action="school-detail" data-id="${s.id}">View school ${icon('arrow',true)}</button></article>`).join('')}</div>`}
function analyticsView(){let users=visibleUsers().filter(u=>u.role==='student'&&(schoolFilter==='all'||u.school===schoolFilter));let avg=Math.round(users.reduce((a,u)=>a+u.score,0)/users.length)||0;return heading('Small steps. Visible progress.','Understand how students are learning across your schools.')+`<div class="filters">${schoolOptions()}</div><div class="stats">${stat('target','Average score',avg,'/100','Student averages in this selection')}${stat('check','Above passing level',users.filter(u=>u.score>=70).length,`/ ${users.length}`,'Students with an average of 70 or more')}${stat('book','Topics completed',users.reduce((a,u)=>a+u.passed,0),'','Across selected student profiles')}</div><div class="analytics-grid"><section class="panel"><h2>Average score by student</h2><p class="small muted" style="margin-top:8px">Select a school to focus your view</p>${chart(users.map(u=>u.score),users.map(u=>u.name.split(' ')[0]))}</section><section class="panel"><h2>Topic completion</h2><p class="small muted" style="margin-top:8px">Sample curriculum performance</p>${[['Numbers & operations',92],['Fractions & decimals',78],['Linear equations',64],['Ratios & proportions',42]].map(([t,v])=>`<div style="margin-top:23px"><div class="row between small"><span>${t}</span><strong>${v}%</strong></div><div class="progress-track" style="margin:10px 0"><span style="width:${v}%"></span></div></div>`).join('')}</section></div>${usersTable(users,false)}`}
function resultsView(){const rs=db.results.filter(r=>EsepterI18n.search(topicName(r.topic),filter)&&(tab==='all'||(tab==='passed'?r.pass:!r.pass)));return heading('See how far you’ve come','Every attempt tells a story. Keep building on what you know.')+`<div class="filters"><div class="segmented">${[['all','All attempts'],['passed','Passed'],['practice','Practice']].map(([v,l])=>`<button data-action="tab" data-id="${v}" class="${tab===v?'active':''}">${l}</button>`).join('')}</div><div class="search-input">${icon('search',true)}<input class="input" id="filter" value="${esc(filter)}" placeholder="Search results…" aria-label="Search results"></div></div>${resultsTable(rs)}`}
function achievementsView(){const items=[['First step','Complete your first topic',db.passed.length>=1,'book'],['Foundation builder','Complete two topics',db.passed.length>=2,'award'],['High achiever','Earn 90 or more points',db.results.some(r=>r.score>=90),'target'],['Halfway there','Complete four topics',db.passed.length>=4,'spark'],['Math explorer','Answer 100 questions',db.results.reduce((a,r)=>a+r.answers,0)>=100,'question'],['Full circle','Complete your learning path',db.passed.length>=studentTopics().length,'shield']];return heading('Milestones worth celebrating','You earn these by showing up, trying, and learning.')+`<div class="school-grid">${items.map(([title,desc,done,i])=>`<article class="school-card" style="${done?'':'opacity:.6'}"><div class="row between" style="margin:0"><span class="medal">${icon(i)}</span>${badge(done?'Earned':'In progress',done?'gold':'gray')}</div><h3>${title}</h3><p class="small muted">${desc}</p></article>`).join('')}</div>`}
function settingsView(){return heading('Make yourself at home','Your profile and learning preferences.')+`<section class="panel settings-panel"><div class="profile-banner"><span class="avatar lg">${initials(roleFull())}</span><div><h2>${esc(roleFull())}</h2><p class="small muted">${db.role[0].toUpperCase()+db.role.slice(1)} · Esepter.kz</p></div></div><form id="profile-form"><div class="form-grid"><div class="field"><label for="profile-name">Full name</label><input class="input" id="profile-name" name="name" value="${esc(roleFull())}" required ${db.role!=='student'?'disabled':''}></div><div class="field"><label for="profile-email">Email address</label><input class="input" id="profile-email" type="email" name="email" value="${esc(db.role==='student'?db.email:db.role==='teacher'?'dana.a@school.kz':'marat.i@school.kz')}" required ${db.role!=='student'?'disabled':''}></div></div>${db.role==='student'?'<button class="btn" type="submit">Save profile</button>':'<p class="hint">This is a sample staff profile. Admins can edit users in Users & roles.</p>'}</form><div class="divider"></div><h3>Preferences</h3><div class="settings-row"><div><strong class="small">Learning reminders</strong><p>Show a reminder in the notifications panel.</p></div><button class="toggle ${db.reminders?'on':''}" role="switch" aria-checked="${db.reminders}" aria-label="Learning reminders" data-action="toggle-reminders"><span></span></button></div><div class="settings-row"><div><strong class="small">Preview data</strong><p>Restore the original sample users, topics, and progress.</p></div><button class="btn light" data-action="reset">Reset demo</button></div><p class="hint" style="margin-top:20px">Changes in this preview stay in this browser. School accounts and shared data require a connected backend.</p></section>`}
function startExam(id){id=Number(id);if(!db.passed.includes(id)&&currentTopic()?.id!==id){toast('Complete your current topic to unlock this one.');return}if(db.exam&&db.exam.topic===id){go('exam');return}if(db.exam){modal('Start a new attempt?',`<p>You have an unfinished attempt in ${esc(topicName(db.exam.topic))}. Starting another will replace it.</p><div class="modal-foot"><button class="btn light" data-action="resume">Resume current</button><button class="btn" data-action="replace-exam" data-id="${id}">Start new</button></div>`);return}newExam(id)}
function newExam(id){db.exam={topic:Number(id),score:0,best:0,passed:false,answers:[],question:null};feedback=null;selectedAnswer=null;nextQuestion();save();go('exam')}
function difficulty(score){return score<=40?'Easy':score<=70?'Medium':'Hard'}
function nextQuestion(){const e=db.exam,d=difficulty(e.score);let available=db.questions.filter(q=>q.topic===e.topic&&q.difficulty===d&&!e.answers.some(a=>a.source===q.id));if(available.length&&Math.random()>.35){const q=available[Math.floor(Math.random()*available.length)];e.question={...q,source:q.id,options:q.mode==='Multiple choice'?q.options.split(',').map(x=>Number(x.trim())):null,explanation:`The correct numeric answer is ${q.answer}.`};}else{e.question=generateQuestion(e.topic,d)}feedback=null;selectedAnswer=null;save()}
function generateQuestion(topic,d){let a=2+Math.floor(Math.random()*7),b=2+Math.floor(Math.random()*10),x=2+Math.floor(Math.random()*10),answer,prompt,explanation;const level=d==='Easy'?1:d==='Medium'?2:3;
 if(topic===1){answer=level===1?a+b:level===2?a*b:a*b+x;prompt=`Calculate ${level===1?`${a} + ${b}`:level===2?`${a} × ${b}`:`(${a} × ${b}) + ${x}`}`;explanation=`Work through the operations to get ${answer}.`}
 else if(topic===2){const n=[2,4,5,8][Math.floor(Math.random()*4)];answer=1/n;prompt=`Write 1/${n} as a decimal.`;explanation=`Divide 1 by ${n}: the result is ${answer}.`}
 else if(topic===4){answer=b*x;prompt=`A ratio is 1 : ${b}. If the first amount is ${x}, what is the second?`;explanation=`Multiply both parts by ${x}. The second amount is ${b} × ${x} = ${answer}.`}
 else if(topic===5){answer=level===1?a*a:a*a*a;prompt=`Calculate ${a}${level===1?'²':'³'}.`;explanation=`Multiply ${a} by itself ${level===1?'two':'three'} times to get ${answer}.`}
 else if(topic===6){answer=180-a*10-b*5;prompt=`Two angles of a triangle are ${a*10}° and ${b*5}°. Find the third angle.`;explanation=`Triangle angles total 180°. Subtract the two given angles to get ${answer}°.`}
 else if(topic===7){answer=a*b;prompt=`A rectangle is ${a} cm wide and ${b} cm long. What is its area in cm²?`;explanation=`Area = width × length = ${a} × ${b} = ${answer} cm².`}
 else if(topic===8){answer=(a+b+x)/3;answer=Math.round(answer*100)/100;prompt=`Find the mean of ${a}, ${b}, and ${x}. Round to 2 decimal places if needed.`;explanation=`Add the values, then divide by 3: (${a} + ${b} + ${x}) / 3 ≈ ${answer}.`}
 else{answer=x;prompt=level===1?`Solve for x: x + ${b} = ${x+b}`:level===2?`Solve for x: ${a}x + ${b} = ${a*x+b}`:`Solve for x: ${a}(x + ${b}) = ${a*(x+b)}`;explanation=level===1?`Subtract ${b} from both sides. x = ${x}.`:level===2?`Subtract ${b}, then divide by ${a}. x = ${x}.`:`Divide both sides by ${a}, then subtract ${b}. x = ${x}.`}
 const numeric=Math.random()>.6;let options=[answer,answer+1,answer+2,answer-1].sort(()=>Math.random()-.5);return{prompt,answer,difficulty:d,mode:numeric?'Numeric':'Multiple choice',options:numeric?null:options,explanation};}
function examView(){if(!db.exam)return `<div class="empty"><h2>Your next step is waiting</h2><p>Choose an unlocked topic to start an exam.</p><a class="btn" href="#topics" style="margin-top:20px">Explore topics</a></div>`;const e=db.exam,q=e.question;return `<div class="exam-layout">${heading(esc(topicName(e.topic)),'Take your time. Every question is another step forward.',`<button class="btn light" data-action="exit-exam">${icon('close',true)}Exit exam</button>`)}<div class="exam-meta"><span>Question <strong>${e.answers.length+(feedback?0:1)}</strong> ${badge(q.difficulty,q.difficulty==='Hard'?'gold':'')}</span><span><strong style="font-size:24px">${e.score}</strong><span class="muted"> / 100 points</span></span></div><div class="scorebar"><span style="width:${e.score}%"></span></div><section class="exam-card"><div class="row between"><span class="eyebrow muted">${q.mode==='Numeric'?'TYPE YOUR ANSWER':'CHOOSE ONE ANSWER'}</span><span class="small muted">${q.difficulty==='Easy'?'+5 / −3':q.difficulty==='Medium'?'+7 / −5':'+10 / −7'} points</span></div><h2 class="question">${esc(q.prompt)}</h2>${q.mode==='Numeric'?`<div class="field" style="max-width:350px;margin:0 auto"><label for="numeric-answer" class="small muted">Your numeric answer</label><input type="number" step="any" class="input" id="numeric-answer" placeholder="Enter your answer" value="${selectedAnswer??''}" ${feedback?'disabled':''}></div>`:`<div class="answer-grid">${q.options.map((v,i)=>`<button class="answer-option ${selectedAnswer===v?'selected':''} ${feedback&&v===q.answer?'correct':feedback&&selectedAnswer===v&&!feedback.correct?'wrong':''}" data-action="select-answer" data-value="${v}" ${feedback?'disabled':''}><span class="letter">${'ABCD'[i]}</span>${v}</button>`).join('')}</div>`}${feedback?`<div class="answer-feedback ${feedback.correct?'':'wrong'}"><strong>${feedback.correct?'That’s right. Well done!':'A good chance to learn.'}</strong> ${esc(q.explanation||`The correct answer is ${q.answer}.`)}<div style="margin-top:6px">${feedback.delta>0?'+':''}${feedback.delta} points${e.passed?' · Topic passed! Your next topic is unlocked.':''}</div></div>`:''}<div class="exam-actions"><span class="small muted">${icon('shield',true)}Your progress saves automatically</span>${feedback?`<div class="row">${e.passed?'<button class="btn light" data-action="finish-exam">Finish</button>':''}<button class="btn" data-action="next-question">${e.score>=100?'See result':'Next question'} ${icon('arrow',true)}</button></div>`:`<button class="btn" data-action="submit-answer" ${selectedAnswer===null?'disabled':''}>Check answer ${icon('arrow',true)}</button>`}</div></section><div class="exam-aside"><span>${icon('target',true)}70 points to pass</span><span>${icon('clock',true)}No time limit</span><span>${icon('book',true)}One question at a time</span></div></div>`}
function submitAnswer(){const e=db.exam;if(!e||feedback||selectedAnswer===null)return;const q=e.question;const correct=Math.abs(Number(selectedAnswer)-Number(q.answer))<.00001;const deltas={Easy:[5,-3],Medium:[7,-5],Hard:[10,-7]};const delta=deltas[q.difficulty][correct?0:1];e.score=Math.max(0,Math.min(100,e.score+delta));e.best=Math.max(e.best,e.score);if(e.score>=70){e.passed=true;if(!db.passed.includes(e.topic))db.passed.push(e.topic)}e.answers.push({prompt:q.prompt,response:selectedAnswer,correct,delta,source:q.source||null});feedback={correct,delta};e.feedback=feedback;e.selection=selectedAnswer;save();render()}
function finishExam(){const e=db.exam;if(!e)return;const r={id:Date.now(),topic:e.topic,score:e.best,finalScore:e.score,pass:e.passed,date:new Date().toISOString().slice(0,10),answers:e.answers.length,history:e.answers};db.results.unshift(r);db.best[e.topic]=Math.max(db.best[e.topic]||0,e.best);db.exam=null;feedback=null;selectedAnswer=null;db.lastResult=r.id;save();go('result')}
function resultView(){const r=db.results.find(x=>x.id===db.lastResult)||db.results[0];return `<div class="exam-layout"><section class="panel result-hero"><span class="eyebrow">${esc(topicName(r.topic))}</span><div class="ring" style="background:conic-gradient(#99b767 0 ${r.score}%,#edf1e5 0)"><div><strong>${r.score}</strong><small>BEST SCORE / 100</small></div></div><h1>${r.pass?'One more milestone, yours.':'Every attempt moves you forward.'}</h1><p class="muted">${r.pass?'You passed this topic. Your progress is saved, and the next topic is ready when you are.':'You haven’t reached 70 points yet. Review what you learned and give it another try.'}</p><div class="row" style="justify-content:center"><a class="btn light" href="#results">View results</a><button class="btn" data-action="start" data-id="${r.pass?(currentTopic()?.id||r.topic):r.topic}">${r.pass?'Continue learning':'Try again'} ${icon('arrow',true)}</button></div><p class="small muted" style="margin-top:24px">${r.answers} questions answered · ${dateLabel(r.date)}</p></section></div>`}
function landing(){return `<div class="landing"><header>${brand()}<div class="row"><a class="btn ghost" href="#login">Log in</a><a class="btn" href="#overview">Explore the platform ${icon('arrow',true)}</a></div></header><section class="intro"><span class="badge">A little progress, every day</span><h1>A clearer path to<br><em>confidence in math.</em></h1><p>A thoughtful learning space for students, teachers, and schools. Build understanding one question, one topic, one small victory at a time.</p><a class="btn" href="#login">Find your next step ${icon('arrow',true)}</a></section><section class="landing-features">${[['book','Learn at your pace','Follow a clear topic path. Questions adapt as your confidence and score grow.'],['users','See every student','Understand progress, spot the places that need support, and help learning move forward.'],['school','Bring your school together','Manage users, organize mathematics content, and follow progress in one shared space.']].map(([i,t,p])=>`<article>${icon(i)}<h3 style="margin-top:18px">${t}</h3><p>${p}</p></article>`).join('')}</section><p class="small muted" style="text-align:center;padding-bottom:30px">Esepter.kz · Built for the next step</p></div>`}
function login(){return `<div class="login"><section class="login-story">${brand()}<div><span class="eyebrow">EVERY STEP COUNTS</span><h1>Big understanding.<br>Small beginnings.</h1><p>A welcoming space to learn, make mistakes, and discover what you’re capable of.</p></div><p class="small">© 2026 Esepter.kz</p></section><section class="login-form"><div><h1>Welcome to your space.</h1><p>Enter your username and password to continue.</p><form id="login-form"><div class="field"><label for="login-username">Username</label><input class="input" id="login-username" name="username" autocomplete="username" placeholder="Enter your username" required></div><div class="field"><label for="login-password">Password</label><div class="password-field"><input class="input" id="login-password" name="password" type="password" autocomplete="current-password" placeholder="Enter your password" required><button type="button" data-action="show-password" aria-label="Show password">Show</button></div></div><p id="login-error" class="form-error" role="alert"></p><button class="btn" type="submit">Log in ${icon('arrow',true)}</button></form><section class="registration-zone"><h3>New to Esepter?</h3><p>Request an account. Your school administrator assigns access.</p><button class="btn light" data-action="register">Register ${icon('arrow',true)}</button></section><details class="login-note"><summary>Demo access</summary><p>Use student, teacher, or admin as the username. Demo password: Esepter2026!</p><p>This is a local preview. Production sign-in requires a backend.</p></details><a href="#welcome" class="btn ghost" style="margin-top:20px">${icon('back',true)}Back to Esepter</a></div></section></div>`}
function registrationForm(){modal('Request registration',`<p>Request an account. Your school administrator assigns access.</p><form id="registration-form">${field('Full name','name')}${field('Email address','email','','email')}<div class="field"><label for="registration-school">School</label><select class="input" id="registration-school" name="school" required><option value="">Choose your school</option>${db.schools.map(s=>`<option value="${esc(s.id)}">${esc(s.name)}</option>`).join('')}</select></div><div class="field"><label for="registration-role">Your role</label><select class="input" id="registration-role" name="role"><option value="student">Student</option><option value="teacher">Teacher</option></select></div><p class="hint">Demo: the request is saved in this browser only and is not sent to a school.</p>${footerButtons('Save registration request')}</form>`)}

function render(){document.title=`${route==='welcome'?'Math for every next step':route==='login'?'Welcome back':route==='exam'?'Your topic exam':menus[db.role].find(n=>n[0]===route)?.[2]||'Your learning space'} · Esepter.kz`;if(route==='welcome'){$('#app').innerHTML=landing();return}if(route==='login'){$('#app').innerHTML=login();return}const allowed=[...menus[db.role].map(n=>n[0]),'settings',...(db.role==='student'?['exam','result']:[])];if(!allowed.includes(route)){route='overview';history.replaceState(null,'','#overview')}if(route==='exam'&&db.exam){feedback=db.exam.feedback||null;selectedAnswer=db.exam.selection??null}const views={overview:()=>db.role==='student'?studentOverview():educatorOverview(),topics:topicView,results:resultsView,students:usersView,users:usersView,questions:questionsView,schools:schoolsView,analytics:analyticsView,achievements:achievementsView,settings:settingsView,exam:examView,result:resultView};$('#app').innerHTML=layout((views[route]||views.overview)());}
function modal(title,body){modalFocus=document.activeElement;$('#overlay').innerHTML=`<div class="modal-backdrop"><section class="modal" role="dialog" aria-modal="true" aria-labelledby="modal-title"><div class="modal-head"><h2 id="modal-title">${title}</h2><button class="iconbtn" data-action="close-modal" aria-label="Close dialog">${icon('close',true)}</button></div>${body}</section></div>`;setTimeout(()=>$('#overlay input, #overlay select, #overlay button')?.focus(),30)}
function closeModal(){$('#overlay').innerHTML='';modalFocus?.focus()}
function field(label,name,value='',type='text',extra=''){return `<div class="field"><label for="form-${name}">${label}</label><input class="input" id="form-${name}" name="${name}" type="${type}" value="${esc(EsepterI18n.t(value))}" data-original-value="${esc(value)}" required ${extra}></div>`}
function footerButtons(label='Save changes'){return `<div class="modal-foot"><button class="btn light" type="button" data-action="close-modal">Cancel</button><button class="btn" type="submit">${label}</button></div>`}
function topicForm(id){const t=db.topics.find(t=>t.id===Number(id));modal(t?'Edit topic':'Create a new topic',`<form id="topic-form" data-id="${t?.id||''}">${field('Topic name','name',t?.name||'')}${field('Short description','desc',t?.desc||'')}<div class="form-grid"><div class="field"><label for="form-school">School</label><select class="input" id="form-school" name="school">${allowedSchools().map(s=>`<option value="${s.id}" ${t?.school===s.id?'selected':''}>${esc(s.name)}</option>`).join('')}</select></div>${field('Topic symbol','symbol',t?.symbol||'x','text','maxlength="3"')}</div><p class="hint">New topics appear at the end of the school’s learning path. Students unlock them by passing the previous topic.</p>${footerButtons(t?'Save topic':'Create topic')}</form>`)}
function questionForm(id){const q=db.questions.find(q=>q.id===Number(id));modal(q?'Edit question':'Add a question',`<form id="question-form" data-id="${q?.id||''}"><div class="field"><label for="form-topic">Topic</label><select class="input" name="topic" id="form-topic">${visibleTopics().map(t=>`<option value="${t.id}" ${q?.topic===t.id?'selected':''}>${esc(t.name)}</option>`).join('')}</select></div>${field('Question','prompt',q?.prompt||'')}<div class="form-grid"><div class="field"><label for="form-difficulty">Difficulty</label><select class="input" id="form-difficulty" name="difficulty">${['Easy','Medium','Hard'].map(d=>`<option ${q?.difficulty===d?'selected':''}>${d}</option>`).join('')}</select></div><div class="field"><label for="form-mode">Answer mode</label><select class="input" id="form-mode" name="mode"><option ${q?.mode==='Numeric'?'selected':''}>Numeric</option><option ${q?.mode==='Multiple choice'?'selected':''}>Multiple choice</option></select></div></div>${field('Correct numeric answer','answer',q?.answer??'','number','step="any"')}<div class="field"><label for="form-options">Four options for multiple choice</label><input class="input" id="form-options" name="options" value="${esc(q?.options||'')}" placeholder="Example: 4, 6, 8, 10"><span class="hint">Separate four distinct numbers with commas and include the correct answer.</span></div><p class="form-error" id="form-error"></p>${footerButtons(q?'Save question':'Add question')}</form>`)}
function userForm(id){const u=db.users.find(u=>u.id===id);modal(u?'Edit user':'Create a user',`<form id="user-form" data-id="${u?.id||''}">${field('Full name','name',u?.name||'')}${field('Email / username','email',u?.email||'','email')}<div class="field"><label for="form-role">Role</label><select class="input" id="form-role" name="role"><option value="student" ${u?.role==='student'?'selected':''}>Student</option><option value="teacher" ${u?.role==='teacher'?'selected':''}>Teacher</option><option value="admin" ${u?.role==='admin'?'selected':''}>Admin</option></select></div><div class="field"><label>School assignments</label>${db.schools.map(s=>`<label class="row" style="font-weight:400"><input type="checkbox" name="schools" value="${s.id}" ${u?.school.split(',').includes(s.id)?'checked':''}>${esc(s.name)}</label>`).join('')}<span class="hint">Students need exactly one school. Teachers may have several. Admins have platform-wide access.</span></div><p class="form-error" id="form-error"></p><p class="hint">This creates a sample account in this browser. Production credentials require a backend.</p>${footerButtons(u?'Save user':'Create user')}</form>`)}
document.addEventListener('click',e=>{const b=e.target.closest('[data-action]');if(!b)return;const a=b.dataset.action,id=b.dataset.id;if(a==='register'){registrationForm();return}if(a==='show-password'){const input=$('#login-password');input.type=input.type==='password'?'text':'password';b.textContent=input.type==='password'?'Show':'Hide';b.setAttribute('aria-label',input.type==='password'?'Show password':'Hide password');return}if(a==='menu'){$('.sidebar')?.classList.toggle('open');$('.mobile-shade')?.classList.toggle('visible');return}if(a==='close-modal'){closeModal();return}if(a==='tab'){tab=id;render();return}if(a==='start'){startExam(id);return}if(a==='topic'){const t=db.topics.find(t=>t.id===Number(id));const unlocked=db.passed.includes(t.id)||currentTopic()?.id===t.id;modal(esc(t.name),`<p>${esc(t.desc)}. Answer questions at your pace and reach 70 points to pass.</p><div class="row" style="margin:20px 0">${badge(db.passed.includes(t.id)?'Completed':unlocked?'Ready to learn':'Locked',unlocked?'':'gray')}<span class="small muted">${t.questions} questions · No time limit</span></div>${unlocked?`<div class="modal-foot"><button class="btn" data-action="launch-topic" data-id="${t.id}">${db.passed.includes(t.id)?'Practice again':'Start learning'} ${icon('arrow',true)}</button></div>`:`<p>Complete <strong>${esc(currentTopic()?.name||'the previous topic')}</strong> to continue along your learning path.</p>`}`);return}if(a==='launch-topic'){closeModal();startExam(id);return}if(a==='resume'){closeModal();go('exam');return}if(a==='replace-exam'){closeModal();newExam(id);return}if(a==='select-answer'){selectedAnswer=Number(b.dataset.value);db.exam.selection=selectedAnswer;save();render();return}if(a==='submit-answer'){submitAnswer();return}if(a==='next-question'){if(db.exam.score>=100){finishExam();return}delete db.exam.feedback;delete db.exam.selection;nextQuestion();render();return}if(a==='finish-exam'){finishExam();return}if(a==='exit-exam'){modal('Take a breather?',`<p>Your current attempt is saved automatically. You can come back to it, or finish now and record your result.</p><div class="modal-foot"><button class="btn light" data-action="pause-exam">Save & leave</button><button class="btn" data-action="end-exam">Finish attempt</button></div>`);return}if(a==='pause-exam'){closeModal();go('overview');return}if(a==='end-exam'){closeModal();finishExam();return}if(a==='add-topic'||a==='edit-topic'){topicForm(id);return}if(a==='add-question'||a==='edit-question'){questionForm(id);return}if(a==='add-user'||a==='edit-user'){userForm(id);return}if(a==='topic-questions'){closeModal();filter=topicName(id);route='questions';history.pushState(null,'','#questions');render();return}if(a==='delete-question'){modal('Delete this question?',`<p>This removes the question from your local question bank. Existing exam results stay in your history.</p><div class="modal-foot"><button class="btn light" data-action="close-modal">Cancel</button><button class="btn danger" data-action="confirm-delete-question" data-id="${id}">Delete question</button></div>`);return}if(a==='confirm-delete-question'){const removed=db.questions.find(q=>q.id===Number(id));const topic=db.topics.find(t=>t.id===removed?.topic);if(topic)topic.questions=Math.max(0,topic.questions-1);db.questions=db.questions.filter(q=>q.id!==Number(id));save();closeModal();render();toast('Question removed.');return}if(a==='add-school'){modal('Add a school',`<form id="school-form">${field('School name','name')}${field('City','city')}<p class="hint">After creating the school, assign teachers and students in Users & roles.</p>${footerButtons('Create school')}</form>`);return}if(a==='school-detail'){const s=db.schools.find(s=>s.id===id);modal(esc(s.name),`<p>${esc(s.city)}, Kazakhstan</p><div class="stats" style="grid-template-columns:1fr 1fr">${stat('users','Student roster',s.students,'','Sample school total')}${stat('book','Teachers',s.teachers,'','Sample school total')}</div><p style="margin-top:20px">${db.users.filter(u=>u.school.split(',').includes(id)).length} editable sample profiles are available for this school.</p><div class="modal-foot"><button class="btn" data-action="school-users" data-id="${id}">View users ${icon('arrow',true)}</button></div>`);return}if(a==='school-users'){closeModal();schoolFilter=id;route='users';history.pushState(null,'','#users');filter='';render();return}if(a==='student-detail'){const u=visibleUsers().find(u=>u.id===id);modal(esc(u.name),`<div class="profile-banner"><span class="avatar lg mint">${initials(u.name)}</span><div><strong>${esc(u.email)}</strong><p style="margin:4px 0 0">${esc(u.role==='admin'?'All schools':u.school.split(',').map(schoolName).join(' · '))}</p></div></div>${u.role==='student'?`<div class="stats" style="grid-template-columns:1fr 1fr">${stat('target','Average score',u.score,'/100','Sample student performance')}${stat('book','Topics passed',u.passed,'/8','Current learning progress')}</div><p style="margin-top:20px">${u.score<70?'A little support with foundational topics could help this student progress.':'This student is building a strong foundation. Encourage regular practice.'}</p>`:`<p>Teacher access includes content management and progress monitoring for assigned schools.</p>`}${db.role==='admin'?`<div class="modal-foot"><button class="btn" data-action="edit-user" data-id="${id}">Edit account</button></div>`:''}`);return}if(a==='result-detail'){const r=db.results.find(r=>r.id===Number(id));modal(esc(topicName(r.topic)),`<div class="row between" style="margin-bottom:20px">${badge(r.pass?'Passed':'Practice attempt',r.pass?'':'gold')}<span class="small muted">${dateLabel(r.date)}</span></div><h1 style="margin-bottom:12px">${r.score}<span class="muted" style="font-size:18px"> / 100 best score</span></h1><p>${r.answers} questions answered${r.finalScore!==undefined?` · ${r.finalScore}/100 final score`:''}</p>${r.history?.length?`<div class="table-wrap"><table><thead><tr><th>Question</th><th>Your answer</th><th>Points</th></tr></thead><tbody>${r.history.map(h=>`<tr><td>${esc(h.prompt)}</td><td>${esc(h.response)} ${h.correct?'✓':'×'}</td><td>${h.delta>0?'+':''}${h.delta}</td></tr>`).join('')}</tbody></table></div>`:'<p>This sample result demonstrates how completed attempts appear. Your own attempts include a full answer history.</p>'}`);return}if(a==='toggle-reminders'){db.reminders=!db.reminders;save();render();return}if(a==='reset'){modal('Reset the preview?',`<p>This restores the original sample data and removes your locally added users, content, and exam attempts.</p><div class="modal-foot"><button class="btn light" data-action="close-modal">Keep my changes</button><button class="btn danger" data-action="confirm-reset">Reset preview</button></div>`);return}if(a==='confirm-reset'){const role=db.role;db=structuredClone(seed);db.role=role;save();closeModal();render();toast('Sample data restored.');return}if(a==='notifications'){modal('Your updates',`<div class="row" style="align-items:flex-start;margin-bottom:24px"><span class="topic-icon">${icon('award')}</span><div><h3>Welcome to your learning space</h3><p style="margin-top:5px">Your school’s topics and progress are ready to explore.</p></div></div>${db.reminders?`<div class="row" style="align-items:flex-start"><span class="topic-icon">${icon('book')}</span><div><h3>A little practice goes a long way</h3><p style="margin-top:5px">Make time for your next topic whenever you’re ready.</p></div></div>`:''}`);return}if(a==='help'){modal('A little guidance',`<h3>For students</h3><p style="margin:8px 0 20px">Start an unlocked topic from your learning path. Correct answers earn points, incorrect answers subtract points. Reach 70 to pass and unlock the next topic. You can continue to 100.</p><h3>For teachers and admins</h3><p style="margin:8px 0 20px">Use Topics and Question bank to manage content. Filter student views by school. Admins can also create schools and manage user assignments.</p><h3>About this preview</h3><p style="margin-top:8px">The Demo selector switches roles. Edits save in this browser. School sign-in, secure access control, and shared records need a backend.</p>`);return}if(a==='search'){modal('Find your next step',`<div class="field"><label for="global-search">Search topics and screens</label><input class="input" id="global-search" placeholder="Try equations, results, or settings…"></div><div id="search-results"><p>Type to find a topic or workspace screen.</p></div>`);return}if(a==='navigate'){closeModal();go(id);return}});
document.addEventListener('input',e=>{if(e.target.id==='filter'){const pos=e.target.selectionStart;filter=e.target.value;render();const f=$('#filter');f?.focus();f?.setSelectionRange(pos,pos)}if(e.target.id==='numeric-answer'){selectedAnswer=e.target.value===''?null:Number(e.target.value);db.exam.selection=selectedAnswer;save();$('[data-action="submit-answer"]').disabled=selectedAnswer===null}if(e.target.id==='global-search'){const q=e.target.value.toLowerCase();const screens=[...menus[db.role],['settings','settings','Settings']].filter(x=>EsepterI18n.search(x[2],q));const topics=visibleTopics().filter(t=>EsepterI18n.search(t.name,q));$('#search-results').innerHTML=q?`${screens.map(([r,i,n])=>`<button class="row" style="width:100%;padding:12px" data-action="navigate" data-id="${r}">${icon(i)}${n}</button>`).join('')}${topics.map(t=>`<button class="row" style="width:100%;padding:12px" data-action="${db.role==='student'?'topic':'topic-questions'}" data-id="${t.id}">${icon('book')}${esc(t.name)}</button>`).join('')}${!screens.length&&!topics.length?'<p>No matches found.</p>':''}`:'<p>Type to find a topic or workspace screen.</p>'}});
document.addEventListener('change',e=>{if(e.target.id==='role-select'){db.role=e.target.value;save();route='overview';filter='';schoolFilter='all';history.replaceState(null,'','#overview');render()}if(e.target.id==='school-filter'){schoolFilter=e.target.value;render()}if(e.target.id==='tab-filter'){tab=e.target.value;render()}});
document.addEventListener('submit',e=>{e.preventDefault();const f=e.target,data=new FormData(f),v=Object.fromEntries(data);for(const input of f.querySelectorAll('[data-original-value]')){if(input.value===EsepterI18n.t(input.dataset.originalValue)){v[input.name]=input.dataset.originalValue}}if(f.id==='login-form'){const username=v.username.trim().toLowerCase();if(!['student','teacher','admin'].includes(username)||v.password!=='Esepter2026!'){$('#login-error').textContent='Incorrect username or password.';return}db.role=username;save();go('overview');return}if(f.id==='registration-form'){db.registrationRequests=db.registrationRequests||[];db.registrationRequests.push({name:v.name.trim(),email:v.email.trim(),school:v.school,role:v.role,createdAt:new Date().toISOString()});save();modal('Request saved',`<p>Your registration request is saved in this browser. In the live platform, the school administrator will review it and provide login details.</p><div class="modal-foot"><button class="btn" data-action="close-modal">Back to login</button></div>`);return}if(f.id==='profile-form'){db.name=v.name.trim();db.email=v.email;save();render();toast('Your profile is updated.');return}if(f.id==='topic-form'){const id=Number(f.dataset.id);if(id){Object.assign(db.topics.find(t=>t.id===id),v)}else db.topics.push({...v,id:Date.now(),questions:0});save();closeModal();render();toast('Topic saved.');return}if(f.id==='question-form'){if(v.mode==='Multiple choice'){const options=v.options.split(',').map(s=>Number(s.trim()));if(options.length!==4||new Set(options).size!==4||options.some(x=>!Number.isFinite(x))||!options.includes(Number(v.answer))){$('#form-error').textContent='Enter four distinct numeric options, including the correct answer.';return}}const id=Number(f.dataset.id);const q={...v,id:id||Date.now(),topic:Number(v.topic),answer:Number(v.answer)};if(id)Object.assign(db.questions.find(q=>q.id===id),q);else{db.questions.push(q);db.topics.find(t=>t.id===q.topic).questions++}save();closeModal();render();toast('Question saved to the bank.');return}if(f.id==='school-form'){db.schools.push({...v,id:'s'+Date.now(),students:0,teachers:0});save();closeModal();render();toast('School created. Add users to get started.');return}if(f.id==='user-form'){const schools=data.getAll('schools');if((v.role!=='admin'&&!schools.length)||(v.role==='student'&&schools.length!==1)){$('#form-error').textContent=v.role==='student'?'Choose exactly one school for this student.':'Choose at least one school for this teacher.';return}if(db.users.some(u=>u.email===v.email&&u.id!==f.dataset.id)){$('#form-error').textContent='This email is already assigned to a user.';return}const old=db.users.find(u=>u.id===f.dataset.id);const u={id:old?.id||'u'+Date.now(),name:v.name.trim(),email:v.email,role:v.role,school:schools.join(','),score:old?.score||0,passed:old?.passed||0};if(old)Object.assign(old,u);else db.users.push(u);if(u.id==='u1'){db.name=u.name;db.email=u.email}save();closeModal();render();toast('User account saved.');return}});
document.addEventListener('keydown',e=>{if(e.key==='Escape'&&$('#overlay').innerHTML)closeModal();if(e.key==='Tab'&&$('#overlay').innerHTML){const nodes=[...$('#overlay').querySelectorAll('button,input,select,textarea,a[href]')].filter(n=>!n.disabled);if(e.shiftKey&&document.activeElement===nodes[0]){e.preventDefault();nodes.at(-1)?.focus()}else if(!e.shiftKey&&document.activeElement===nodes.at(-1)){e.preventDefault();nodes[0]?.focus()}}});
render();
